    # Payload находится в here-document, поэтому установка одинаково работает
    # из файла и через `wget -O- URL | sh`, где $0 указывает на `sh`.
    base64 -d <<'__FORKOP_SC_PAYLOAD__' | tar -xzf - -C "$TMP_DIR"
